INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_fa96d36','service_pool_001','Wudadao Stroll',4,'The change and cancellation policy sounds lenient when explained verbally, but the written terms are a different matter. The schedule is a little rushed; fitting three activities into two hours is too packed.',NULL,'2026-05-14T12:09:41+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_y343471','service_pool_001','one pottery bowl',4,'It is a bit far from the subway station, about a 15-minute walk, and there is some sun exposure in summer. The invoiced amount differed from the actual payment by a few dozen yuan; they said coupons could not be invoiced. They could only issue an invoice for materials sales, and it took ages to write the description. Two additional guide signs were added on-site at no extra charge.','Sign','2026-06-12T22:18:47+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_wb30281','catering_pool_002','Photos taken without retouching',5,'The front desk phone is always busy, so orders can only be placed online. Two portions were delivered incorrectly, and sending replacements took half an hour. The process was a little rushed; fitting three steps into two hours was too tight. Because the number of people was temporarily reduced by five, the corresponding materials fee was refunded.',NULL,'2026-06-19T15:04:05+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_e9e3435','catering_pool_002','Lao Zhangtou',5,'Orders must be placed 48 hours in advance; last-minute additions are not possible. An electronic invoice was issued on the spot, and the billing information was checked very carefully. The value for money is average, but it is conveniently close to the office.',NULL,'2026-05-06T20:22:47+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_fd27fa2','venue_pottery_003','Overtime-Free Person',5,'The courtyard is in a hutong, and taxis can only stop at the entrance to the lane. Family members can participate too, and children have a separate small platform. It is billed as a cultural experience service fee and paid by corporate bank transfer; the finance department processed the reimbursement without any issues. There is a limit on the number of rescheduling requests; the second rescheduling requires paying the deposit again.',NULL,'2026-05-12T21:02:14+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_a7adb04','venue_pottery_003','Traveling with children',4,'An electronic invoice was issued on the spot, and the header information was checked very carefully. It is a seven- or eight-minute walk from Exit of Metro Line 1, and there is a sign at the intersection. I will come again, but next time I will confirm the invoice details in advance.',NULL,'2026-05-30T22:44:38+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_yf6ef5d','venue_pottery_004','An accountant who loves crafts',5,'The firing schedule coincided with peak season, so it was pushed back by one week. Free seating allowed colleagues from different departments to interact naturally, and the host did not force anyone to display their work. Cancellations incur a 30 percent fee, which is stricter than other studios.',NULL,'2026-05-17T16:58:08+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_f75c537','venue_pottery_004','Lao Zhangtou',4,'Unfired pieces are piled in the corner; it looks a bit messy but has a lived-in feel. Family members can participate too, and children have their own small worktables. The teacher handles glazing the finished pieces uniformly; we only choose the colors. It''s a street-front shop, and navigation can take you right there, but the sign is small and it''s easy to walk past.',NULL,'2026-06-08T20:39:53+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_b7d1a64','venue_pottery_005','Lao Zhangtou',4,'Parking is difficult at the entrance, so we parked in the basement of the office building next door for two hours at ten yuan. The meal-box label said it contained gluten, so colleagues with allergies avoided it in advance. There is one jin of mud per person; more can be added if it isn''t enough, and the additional portion is charged separately.',NULL,'2026-06-13T10:22:44+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v9c1d9c','venue_pottery_005','Nankai''s Cat',5,'More than 20 people came on the private-booking day; the two rows of pottery wheels fit perfectly without being cramped. Everything was collected ten days later; the administrative staff went to pick it up, and the registration was very clear.',NULL,'2026-06-28T16:43:53+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v3f34b3','catering_pool_006','Marketing Department Amy',5,'Because the group size was temporarily reduced by five, the corresponding overpaid material fee was refunded. Organizing everything was easier than expected, and the contact person responded quickly. The invoice was issued as a catering service fee, so reimbursement was no problem. An electronic invoice was issued on the spot, and the billing information was checked very carefully.',NULL,'2026-06-27T09:18:11+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x3af9c6','catering_pool_006','Marketing Department Amy',5,'Bottling the beverages is cleaner than self-serving from a large dispenser. I asked whether a training fee could be issued, but was told there was no such category. Organizing it was easier than expected, and the contact person responded quickly. The invoice information was entered correctly the first time, and the invoice was issued the next day.',NULL,'2026-06-22T22:42:47+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_u730b6c','catering_pool_007','Ceramics beginner',5,'An electronic invoice was issued on the spot, and the header information was checked very carefully. The value for money was average, but it has the advantage of being close to the company. Half was prepaid, and the balance was settled within one week after the event ended. The invoice information was entered correctly the first time, and the invoice was ready the next day.','Refreshment table','2026-05-13T20:22:22+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_y8345f1','catering_pool_007','Legal Affairs Xiao Sun',4,'The front desk phone is always busy, so orders can only be placed online. I asked whether they could issue an invoice for the training fee, but they said there was no such category. The value for money was average, but its advantage is that it''s close to the office. Because the number of people was temporarily reduced by five, the corresponding materials fee was refunded.',NULL,'2026-05-30T19:09:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v5e9bd7','venue_pottery_008','An accountant who loves crafts',4,'You have to make the trip yourself to collect the items; there is no delivery. Ventilation is average, and the glaze smell dissipates slowly. Rescheduling three days in advance incurred no fee, and the attitude was quite good.',NULL,'2026-06-26T16:11:19+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_ua5140b','venue_pottery_008','Wudadao Stroll',5,'There is no food service; we ordered takeout ourselves. Rescheduling 3 days in advance incurred no fee, and the attitude was very good.',NULL,'2026-05-23T16:36:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_cb1ad9a','catering_pool_009','Administration Xiao Zhao',3,'A separate option for whether beef and lamb were included was labeled with color coding. It rained that day, so they couldn’t come; it was rescheduled for the following week, with only the price difference paid. The delivery rider took it directly to the meeting room and didn’t make us go downstairs to carry it. I asked whether a training fee invoice could be issued, but was told there was no such category.',NULL,'2026-05-08T15:46:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_w03a32c','catering_pool_009','Silent Majority',3,'I would come again, but next time I would confirm the invoice in advance. The corresponding materials fee for the extra item was refunded. Orders must be placed 48 hours in advance; last-minute additions are not possible.',NULL,'2026-05-07T18:34:53+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_y9da26e','venue_pottery_010','a girl who is 1.8 meters tall',4,'There are steps at the entrance; colleagues with strollers or mobility issues should take care. There is a limit on the number of date changes; a second change requires paying the deposit again. The light meals are sandwiches and salads, with the ingredients listed; colleagues who do not eat beef or mutton have separate portions. Unfired pieces are stacked in the corner, looking a little messy but giving the place a lived-in feel.','Rest Area','2026-05-19T12:52:00+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_w1f66d5','venue_pottery_010','Silent Majority',5,'There is no food service; we ordered takeout ourselves. The finished pieces were glazed by the instructor as a group, and we only chose the colors. The process was relaxing, with no mandatory presentation segment, which was great. The invoice category was listed as handicrafts, and we were asked to provide an additional explanation when submitting the reimbursement.',NULL,'2026-05-24T19:47:47+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_bd44bb6','venue_pottery_011','Xiao Chen from Finance',5,'There was a separate sink, so everything could be rinsed immediately afterward. The venue was advertised as accommodating thirty people, but once space for bags and display racks was taken into account, twenty-five people already made it very crowded. Half was prepaid, and the remaining balance was to be settled within one week after the event ended. They could only issue an invoice for material sales, which our finance department would not accept, so we ultimately paid it ourselves.',NULL,'2026-05-08T19:48:47+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_b209f2e','venue_pottery_011','Intern Xiao Zhou',4,'On the 4th floor of the shopping mall; go up with the escalator and you will see it. Light meals cost extra, about 60 per person.',NULL,'2026-06-06T14:51:08+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_ye4506b','service_pool_012','Intern Xiao Zhou',5,'After exiting Metro Line 1, walk for seven or eight minutes; there is a sign at the intersection. The 2,030th activity setup workshop, Binjiang Road branch · intern Xiao Zhou, with the old record summarized as “average value for money, but its advantage is… advantage is being close to the company.” We brought the materials ourselves; they only provided the dimensions.','Equipment placement','2026-05-20T13:59:08+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_db4d5f3','service_pool_012','Team-Building Lead',4,'The schedule is a bit rushed; 3 segments in 2 hours is too much. It rained that day and we couldn''t make it, so it was moved to next week and only the price difference was paid.',NULL,'2026-06-24T09:37:44+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_y603b59','service_pool_013','Expert at slacking off',3,'Cancellation incurs a 30% fee, which is stricter than competitors. It is a street-front shop that navigation can take you directly to, but the small sign makes it easy to miss.',NULL,'2026-05-12T14:37:28+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d3f3c95','service_pool_013','Silent Majority',4,'We bring our own materials; they only provide the dimensions. Cancellations incur a 30% deduction, which is stricter than comparable providers.',NULL,'2026-05-06T15:06:31+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_w4e7439','service_pool_014','Team-Building Lead',4,'The process was relaxing, with no mandatory presentation segment, which was great. The photo documentation was produced quickly, and the initial edit was provided the next day. The invoiced amount differed from the actual payment by several dozen yuan; they said the coupon could not be invoiced. The courtyard is in a hutong, and taxis can only stop at the entrance.',NULL,'2026-06-17T21:39:22+08:00');
